3,2,3009001,1"--------------------------------------逻辑部分---------------------------------------------打开付费礼包function NewWarriorReward_Open(nItemId)	--检查天石	local nCostCP = tNewWarriorReward_Reward[nItemId]["CostCP"]	if not (Get_UserEMoney() >= nCostCP) then		Sys_MsgBox(tNewWarriorReward_Text["Msg"]["NoCPs"])		return	end		--空间不足	local nSpace = tNewWarriorReward_Reward[nItemId]["NeedSpace"]	if not User_CheckLeftSpace(nSpace) then		local sTip = string.format(tNewWarriorReward_Text["Msg"]["NoSpace"],nSpace)		Sys_MsgBox(sTip)		return	end	--扣天石，给奖励	if Item_ChkItem(nItemId) and User_AddEMoney(-nCostCP) then		RewardTemplate_UseItem(tNewWarriorReward_Reward[nItemId])	end	endfunction NewWarriorReward_ChooseOne(nItemId,nIndex)	local nEvent = tNewWarriorReward_Reward[nItemId][nIndex]["EventType"]	local nType = tNewWarriorReward_Reward[nItemId][nIndex]["DataType"]	local nTimesLimit = tNewWarriorReward_Data["OpenTimes"][nItemId]	local nData = Get_UserStatisticValue(nEvent,nType,nUserId) / 10000		if nData >= nTimesLimit then		if Item_ChkItem(nItemId) and Item_DelItem(nItemId) then			RewardTemplate_UseItem(tNewWarriorReward_Reward[nItemId][nIndex])		end		return	end		if Item_ChkItem(nItemId) then		RewardTemplate_UseItem(tNewWarriorReward_Reward[nItemId][nIndex])	endendfunction NewWarriorReward_OpenLetter(nItemId)	if Item_ChkItem(nItemId) then		RewardTemplate_UseItem(tNewWarriorReward_Reward[nItemId])	endend--------------------------------------物品配置--------------------------------------------- 总礼包（免费）tItem[3300274] = tItem[3300274] or {}tItem[3300275] = tItem[3300274] or {}tItem[3300276] = tItem[3300274] or {}tItem[3300279] = tItem[3300274] or {}tItem[3300274]["Function"] = function(nItemId,sItemName)	RewardTemplate_UseItem(tNewWarriorReward_Reward[nItemId])end-- 总礼包（付费）tItem[3300282] = tItem[3300282] or {}tItem[3300282]["DialogueText"] = tNewWarriorReward_Text[3300282]tItem[3300282]["Text1-1"] = {111,112,113}tItem[3300282][